(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.01+t*0.15)*8+Math.cos((x-y)*0.012-t*0.18)*6;
  wy += Math.cos((x-y)*0.011+t*0.17)*7+Math.sin((x+y)*0.013-t*0.14)*5;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.6],
