    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.65],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.75],
    [80+Math.sin(t*0.45+3)*110,40+Math.cos(t*0.65+2)*60,0.11,1.4,0.55],
    [400+Math.cos(t*0.55+1)*70,220+Math.sin(t*0.75)*50,0.085,2.1,0.7]
  ];
  let aS=0,iS=0,a2=0,i2=0;
  for(const[sX,sY,f,sp,w]of src){
