  }
  const tw=src.reduce((a,s)=>a+s[4],0);
  aS/=tw;iS/=tw;a2/=tw;i2/=tw;
  const cross=Math.tanh((aS*i2-iS*a2)*3.5)*0.4;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.07-sy*0.05+t*1.3)+Math.cos(sx*0.05+sy*0.08-t*1.0))/2;
  const micro=Math.sin(sx*0.25+t*2.5)*Math.sin(sy*0.25-t*1.8)*0.15;
  const bgBlend=bg*0.5+bg2*0.3+micro+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
