  const cell2=Math.sin(sx*0.12+sy*0.08)*Math.cos(sx*0.08-sy*0.12+t*0.5)*0.15;
  const rd1=Math.tanh((aS-iS*0.7+bgBlend*0.3+spiral)*2.2);
  const rd2=Math.tanh((a2-i2*0.65+spiral2+vortex)*2.0);
  const merged=Math.tanh((rd1*0.6+rd2*0.4+cross+cell+cell2)*1.4);
