  const pal=[
    [5,12,52],[10,35,85],[12,60,108],[16,90,118],[20,120,125],
    [45,148,118],[90,168,105],[150,178,80],[195,172,60],
    [210,148,55],[215,118,62],[200,88,68],[175,60,72],
